CREATE TABLE IF NOT EXISTS clients (id_client INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, full_name VARCHAR(150) NOT NULL, phone VARCHAR(20) NOT NULL, email VARCHAR(150) NOT NULL);
CREATE TABLE IF NOT EXISTS employees (id_employee INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, full_name VARCHAR(150) NOT NULL, phone VARCHAR(20) NOT NULL, position VARCHAR(100) NOT NULL, login VARCHAR(50) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS brigades (id_brigade INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, brigade_name VARCHAR(100) NOT NULL, phone VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS installers (id_installer INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, full_name VARCHAR(150) NOT NULL, phone VARCHAR(20) NOT NULL, id_brigade INTEGER NOT NULL REFERENCES brigades(id_brigade));
CREATE TABLE IF NOT EXISTS services (id_service INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(150) NOT NULL, description TEXT NOT NULL, base_price DECIMAL(10,2) NOT NULL CHECK (base_price >= 0), executor_type VARCHAR(20) NOT NULL DEFAULT 'either', requires_visit BOOLEAN NOT NULL DEFAULT TRUE, requires_date BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS applications (id_application INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_client INTEGER NOT NULL REFERENCES clients(id_client), id_service INTEGER NOT NULL REFERENCES services(id_service), id_employee INTEGER REFERENCES employees(id_employee), id_installer INTEGER REFERENCES installers(id_installer), id_brigade INTEGER REFERENCES brigades(id_brigade), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, preliminary_area DECIMAL(8,2) NOT NULL CHECK (preliminary_area > 0), installation_address VARCHAR(255) NOT NULL, comment TEXT, status VARCHAR(50) NOT NULL, cancellation_reason TEXT, installation_date TIMESTAMP, privacy_consent_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id_product INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(150) NOT NULL, description TEXT NOT NULL, price DECIMAL(10,2) NOT NULL CHECK (price >= 0), stock_quantity INTEGER NOT NULL DEFAULT 0 CHECK (stock_quantity >= 0));
CREATE TABLE IF NOT EXISTS orders (id_order INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_client INTEGER NOT NULL REFERENCES clients(id_client), id_employee INTEGER REFERENCES employees(id_employee), id_application INTEGER REFERENCES applications(id_application), order_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, total_amount DECIMAL(10,2) NOT NULL CHECK (total_amount >= 0), status VARCHAR(50) NOT NULL, cancellation_reason TEXT, comment TEXT, payment_access_token VARCHAR(128));
CREATE TABLE IF NOT EXISTS order_items (id_order_item INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_order INTEGER NOT NULL REFERENCES orders(id_order) ON DELETE CASCADE, id_product INTEGER NOT NULL REFERENCES products(id_product), quantity INTEGER NOT NULL CHECK (quantity > 0), purchase_price DECIMAL(10,2) NOT NULL CHECK (purchase_price >= 0));
CREATE TABLE IF NOT EXISTS payments (id_payment INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_order INTEGER NOT NULL REFERENCES orders(id_order) ON DELETE CASCADE, amount DECIMAL(10,2) NOT NULL CHECK (amount >= 0), payment_date TIMESTAMP, payment_method VARCHAR(50) NOT NULL, status VARCHAR(50) NOT NULL, transaction_number VARCHAR(150));
CREATE TABLE IF NOT EXISTS deliveries (id_delivery INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_order INTEGER NOT NULL UNIQUE REFERENCES orders(id_order) ON DELETE CASCADE, delivery_method VARCHAR(50) NOT NULL, address VARCHAR(255), delivery_date TIMESTAMP, status VARCHAR(50) NOT NULL);

ALTER TABLE products ADD COLUMN IF NOT EXISTS image VARCHAR(255);
CREATE UNIQUE INDEX IF NOT EXISTS clients_phone_unique ON clients(phone);
CREATE INDEX IF NOT EXISTS applications_brigade_date_idx ON applications(id_brigade, installation_date);
CREATE INDEX IF NOT EXISTS applications_installer_date_idx ON applications(id_installer, installation_date);
CREATE INDEX IF NOT EXISTS orders_application_idx ON orders(id_application);
ALTER TABLE orders ADD COLUMN IF NOT EXISTS comment TEXT;
ALTER TABLE applications ADD COLUMN IF NOT EXISTS privacy_consent_at TIMESTAMP;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS privacy_consent_at TIMESTAMP;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS payment_access_token VARCHAR(128);
ALTER TABLE deliveries ADD COLUMN IF NOT EXISTS carrier VARCHAR(100);
CREATE UNIQUE INDEX IF NOT EXISTS orders_payment_access_token_idx ON orders(payment_access_token) WHERE payment_access_token IS NOT NULL;
